41	func detectAndroidMotionMedia(blob []byte, mimeType, attachmentUID string) *storepb.MotionMedia {
42		if mimeType != "image/jpeg" && mimeType != "image/jpg" {
43			return nil
44		}
45	
46		detection := motionphoto.DetectJPEG(blob)
47		if detection == nil {
48			return nil
49		}
50	
51		return &storepb.MotionMedia{
52			Family:                  storepb.MotionMediaFamily_ANDROID_MOTION_PHOTO,
53			Role:                    storepb.MotionMediaRole_CONTAINER,
54			GroupId:                 attachmentUID,
55			PresentationTimestampUs: detection.PresentationTimestampUs,
56			HasEmbeddedVideo:        true,
57		}
58	}
